'use client';

import { useEffect, useMemo, useState } from 'react';
import { supabase } from '../lib/supabase';

// Imagens da marca original incorporadas para permitir atualizacao de um unico arquivo.
const LOGO_PM = 'data:image/jpeg;base64,';
const MONOGRAMA_PM = 'data:image/jpeg;base64,';

const RECEPCIONISTAS = ['Marcela', 'Sueli', 'Patrícia', 'Isabela'];
// Associação temporária do evento de teste. Não equivale a autenticação.
const EVENTOS_TESTE = { '01/11/2026': '017dd324-dbba-4674-ba24-b7ed7e5cfaa0' };
// Aceita apenas numeros no teclado do celular e insere barras automaticamente.
function formatarDataEvento(valor) {
  const numeros = String(valor).replace(/\D/g, '').slice(0, 8);
  if (numeros.length <= 2) return numeros;
  if (numeros.length <= 4) return `${numeros.slice(0, 2)}/${numeros.slice(2)}`;
  return `${numeros.slice(0, 2)}/${numeros.slice(2, 4)}/${numeros.slice(4)}`;
}

function dataValida(valor) {
  if (!/^\d{2}\/\d{2}\/\d{4}$/.test(valor)) return false;
  const [dia, mes, ano] = valor.split('/').map(Number);
  const data = new Date(ano, mes - 1, dia);
  return data.getFullYear() === ano && data.getMonth() === mes - 1 && data.getDate() === dia;
}

function apresentarMesa(valor) {
  const texto = String(valor ?? '').trim();
  if (!texto) return 'Mesa a definir';
  if (/^\d+$/.test(texto)) return `Mesa ${texto.padStart(2, '0')}`;
  if (/^mesa\s+/i.test(texto)) return texto;
  if (/^setor\s+/i.test(texto)) return texto;
  return texto;
}

const UUID_RE = /^[0-9a-f]{8}-[0-9a-f]{4}-[1-8][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i;

export default function Home() {
  const [convidados, setConvidados] = useState([]);
  const [checkins, setCheckins] = useState([]);
  const [busca, setBusca] = useState('');
  const [filtro, setFiltro] = useState('todos');
  const [mesaSelecionada, setMesaSelecionada] = useState('');
  const [alterandoMesaId, setAlterandoMesaId] = useState(null);
  const [novaMesa, setNovaMesa] = useState('');
  const [recepcionista, setRecepcionista] = useState(RECEPCIONISTAS[0]);
  const [eventoId, setEventoId] = useState('');
  const [codigoEvento, setCodigoEvento] = useState('');
  const [acessoMensagem, setAcessoMensagem] = useState('');
  const [carregando, setCarregando] = useState(false);
  const [erro, setErro] = useState('');
  const [aviso, setAviso] = useState('');
  const [ocupado, setOcupado] = useState(false);
  const [faixas, setFaixas] = useState(null);
  const [editandoFaixas, setEditandoFaixas] = useState(false);
  const [limiteIsento, setLimiteIsento] = useState('');
  const [limiteMeia, setLimiteMeia] = useState('');
  const [salvandoFaixas, setSalvandoFaixas] = useState(false);
  const [mensagemFaixas, setMensagemFaixas] = useState('');

  useEffect(() => {
    let ativo = true;
    setFaixas(null);
    setMensagemFaixas('');
    if (!eventoId) return;
    supabase.from('faixas_buffet').select('isento_ate,meia_ate')
      .eq('evento_id', eventoId).maybeSingle().then(({data,error}) => {
        if (!ativo) return;
        if (error) {
          setMensagemFaixas('Faixas ainda não disponíveis neste evento. Verifique a configuração no Supabase.');
        } else if (data) {
          setFaixas(data);
          setLimiteIsento(String(data.isento_ate));
          setLimiteMeia(String(data.meia_ate));
        }
      });
    return () => { ativo = false; };
  }, [eventoId]);

  async function guardarFaixas(e) {
    e.preventDefault();
    const isento = Number(limiteIsento);
    const meia = Number(limiteMeia);
    if (limiteIsento === '' || limiteMeia === '' || !Number.isInteger(isento) || !Number.isInteger(meia) || isento < 0 || meia < isento || meia > 17) {
      setMensagemFaixas('Informe limites de idade válidos entre 0 e 17 anos, em ordem crescente.');
      return;
    }
    setSalvandoFaixas(true);
    setMensagemFaixas('');
    const {error} = await supabase.from('faixas_buffet').upsert({evento_id:eventoId, isento_ate:isento, meia_ate:meia}, {onConflict:'evento_id'});
    if (error) setMensagemFaixas(`Não foi possível salvar as faixas: ${error.message}`);
    else {
      setFaixas({isento_ate:isento, meia_ate:meia});
      setEditandoFaixas(false);
      setMensagemFaixas('Faixas salvas para este evento.');
    }
    setSalvandoFaixas(false);
  }

  const idValido = UUID_RE.test(eventoId);

  function entrar(evento) {
    evento.preventDefault();
    const codigo = formatarDataEvento(codigoEvento.trim());
    if (!dataValida(codigo)) {
      setAcessoMensagem('Informe uma data válida com 8 números. Exemplo: 01112026.');
      return;
    }
    if (!RECEPCIONISTAS.includes(recepcionista)) {
      setAcessoMensagem('Escolha uma recepcionista da equipe.');
      return;
    }
    const id = EVENTOS_TESTE[codigo];
    if (!id) {
      setAcessoMensagem('Código ainda não cadastrado nesta versão de teste. Para este teste, use 01/11/2026.');
      return;
    }
    setAcessoMensagem('');
    setEventoId(id);
  }

  function sair() {
    setEventoId('');
    setConvidados([]);
    setCheckins([]);
    setBusca('');
    setFiltro('todos');
    setMesaSelecionada('');
    setAlterandoMesaId(null);
    setErro('');
    setAviso('');
  }

  async function carregar(id, preservarErro = false) {
    if (!UUID_RE.test(id)) return;
    setCarregando(true);
    if (!preservarErro) setErro('');
    setAviso('');
    try {
      const [resultadoConvidados, resultadoCheckins] = await Promise.all([
        supabase.from('convidados').select('*').eq('evento_id', id).order('nome'),
        supabase.from('checkins').select('id,convidado_id').eq('evento_id', id)
      ]);
      if (resultadoConvidados.error) {
        setErro(`Falha ao consultar convidados: ${resultadoConvidados.error.message}`);
        setConvidados([]);
        return;
      }
      if (resultadoCheckins.error) {
        setErro(`Falha ao consultar presenças: ${resultadoCheckins.error.message}`);
        setConvidados(resultadoConvidados.data || []);
        setCheckins([]);
        return;
      }
      const dados = resultadoConvidados.data || [];
      setConvidados(dados);
      setCheckins(resultadoCheckins.data || []);
      if (dados.length === 0) {
        setAviso('A consulta não retornou convidados. Como existem registros no Supabase, precisamos verificar a autorização de leitura (RLS) e a associação com este evento. Nenhum dado foi apagado.');
      }
    } catch (e) {
      setErro(`Não foi possível acessar o Supabase: ${e?.message || 'erro de conexão'}`);
    } finally {
      setCarregando(false);
    }
  }

  useEffect(() => {
    setConvidados([]);
    setCheckins([]);
    setErro('');
    setAviso('');
    if (!idValido) return;
    let ativo = true;
    // Evita requisições enquanto o identificador está sendo digitado.
    const canal = supabase
      .channel(`recepcao-${eventoId}`)
      .on('postgres_changes', { event: '*', schema: 'public', table: 'convidados', filter: `evento_id=eq.${eventoId}` }, () => { if (ativo) carregar(eventoId, true); })
      .on('postgres_changes', { event: '*', schema: 'public', table: 'checkins', filter: `evento_id=eq.${eventoId}` }, () => { if (ativo) carregar(eventoId, true); })
      .subscribe();
    carregar(eventoId);
    return () => { ativo = false; supabase.removeChannel(canal); };
  }, [eventoId, idValido]);

  const presentesIds = useMemo(() => new Set(checkins.map(c => c.convidado_id)), [checkins]);
  const lista = convidados.filter(c => {
    const encontrado = (c.nome || '').toLowerCase().includes(busca.toLowerCase());
    const presente = presentesIds.has(c.id);
    return encontrado && (filtro === 'todos' || (filtro === 'presentes' && presente) || (filtro === 'pendentes' && !presente));
  });
  const mesas = Array.from(new Set(convidados.map(c => apresentarMesa(c.mesa))))
    .sort((a, b) => a.localeCompare(b, 'pt-BR', {numeric: true}));
  const mesaAtual = mesas.includes(mesaSelecionada) ? mesaSelecionada : (mesas[0] || '');
  const convidadosDaMesa = convidados.filter(c => apresentarMesa(c.mesa) === mesaAtual);
  const presentesDaMesa = convidadosDaMesa.filter(c => presentesIds.has(c.id)).length;
  const presentes = convidados.filter(c => presentesIds.has(c.id)).length;
  // Apenas registros com idade infantil confirmada são contabilizados como crianças.
  const ehCrianca = (c) => c.idade !== null && c.idade !== undefined && c.idade !== '' && Number.isInteger(Number(c.idade)) && Number(c.idade) >= 0 && Number(c.idade) < 18;
  const criancas = convidados.filter(ehCrianca);
  const criancasPresentes = criancas.filter(c => presentesIds.has(c.id)).length;
  const adultosPresentes = presentes - criancasPresentes;
  const criancasIsentas = faixas ? criancas.filter(c => presentesIds.has(c.id) && Number(c.idade) <= faixas.isento_ate).length : 0;
  const criancasMeia = faixas ? criancas.filter(c => presentesIds.has(c.id) && Number(c.idade) > faixas.isento_ate && Number(c.idade) <= faixas.meia_ate).length : 0;
  const criancasIntegral = faixas ? criancas.filter(c => presentesIds.has(c.id) && Number(c.idade) > faixas.meia_ate).length : 0;



  async function check(convidado) {
    if (ocupado || !idValido) return;
    setOcupado(true);
    setErro('');
    try {
      const presente = presentesIds.has(convidado.id);
      const operacao = presente
        ? supabase.from('checkins').delete().eq('evento_id', eventoId).eq('convidado_id', convidado.id)
        : supabase.from('checkins').insert({ evento_id: eventoId, convidado_id: convidado.id });
      const { error } = await operacao;
      if (error) {
        // Nao apagar este aviso ao atualizar a lista: ele informa a causa da falha.
        setErro(`Check-in não realizado: ${error.message}${error.code ? ` (código ${error.code})` : ''}`);
        return;
      }
      await carregar(eventoId);
      // Confirmar pelo banco, sem declarar sucesso apenas por ter clicado.
      const { data: confirmacao, error: erroConfirmacao } = await supabase
        .from('checkins').select('id').eq('evento_id', eventoId)
        .eq('convidado_id', convidado.id).limit(1);
      if (erroConfirmacao) {
        setErro(`Não foi possível confirmar o check-in: ${erroConfirmacao.message}`);
      } else if (Boolean(confirmacao?.length) === presente) {
        setErro('O banco não confirmou a alteração da presença. Tente atualizar a página e confira o registro antes de tentar novamente.');
      }
    } catch (e) {
      setErro(`Falha no check-in: ${e?.message || 'erro de conexão'}`);
    } finally {
      setOcupado(false);
    }
  }

  async function confirmarIdade(convidado) {
    if (ocupado || !idValido) return;
    const resposta = window.prompt(`Idade da criança ${convidado.nome} (0 a 17 anos):`, convidado.idade == null ? '' : String(convidado.idade));
    if (resposta === null) return;
    const texto = resposta.trim();
    if (!/^(?:[0-9]|1[0-7])$/.test(texto)) {
      setErro('Informe a idade completa da criança, de 0 a 17 anos.');
      return;
    }
    setOcupado(true);
    setErro('');
    try {
      const { data, error } = await supabase.from('convidados')
        .update({ idade: Number(texto) })
        .eq('evento_id', eventoId)
        .eq('id', convidado.id)
        .select('id,idade');
      if (error) {
        setErro(`Não foi possível salvar a idade: ${error.message}`);
      } else if (!data?.length) {
        setErro('A idade não foi confirmada pelo banco. Verifique a permissão de atualização.');
      } else {
        // Confirmação persistida no banco, sem mexer no estado dos check-ins.
        setConvidados(atual => atual.map(c => c.id === convidado.id ? {...c, idade: data[0].idade} : c));
      }
    } catch (e) {
      setErro(`Não foi possível atualizar a idade: ${e?.message || 'erro de conexão'}`);
    } finally {
      setOcupado(false);
    }
  }

  function abrirAlteracaoMesa(convidado) {
    setAlterandoMesaId(convidado.id);
    setNovaMesa(String(convidado.mesa ?? ''));
    setErro('');
  }

  async function salvarMesa(convidado) {
    const destino = novaMesa.trim();
    if (!destino) {
      setErro('Informe a nova mesa ou setor.');
      return;
    }
    if (ocupado) return;
    setOcupado(true);
    setErro('');
    try {
      // Grava somente a mesa: idade e presença permanecem intactas.
      const { data, error } = await supabase.from('convidados')
        .update({mesa: destino})
        .eq('evento_id', eventoId)
        .eq('id', convidado.id)
        .select('id,mesa');
      if (error) {
        setErro(`Não foi possível alterar a mesa: ${error.message}`);
      } else if (!data?.length) {
        setErro('O banco não confirmou a mudança de mesa. Verifique a permissão de atualização.');
      } else {
        setConvidados(atual => atual.map(c =>
          c.id === convidado.id ? {...c, mesa: data[0].mesa} : c));
        setAlterandoMesaId(null);
      }
    } catch (e) {
      setErro(`Falha ao mudar a mesa: ${e?.message || 'erro de conexão'}`);
    } finally {
      setOcupado(false);
    }
  }

  async function adicionar() {
    if (!idValido) return;
    const nome = window.prompt('Nome do convidado extra:');
    if (!nome?.trim()) return;
    const mesa = window.prompt('Mesa ou setor:') || 'A definir';
    setErro('');
    const { error } = await supabase.from('convidados').insert({ evento_id: eventoId, nome: nome.trim(), mesa });
    if (error) setErro(`Não foi possível incluir o convidado: ${error.message}`);
    else await carregar(eventoId);
  }

  return (
    <main className="shell">
      {!eventoId ? (
        <>
          <header>
            <div>
              <div style={{background:"#fff",borderRadius:18,padding:12,width:"min(100%,260px)",marginBottom:16}}><img src={LOGO_PM} alt="Patrícia Matavelli Cerimonialista — logomarca oficial" style={{display:"block",width:"100%",height:"auto"}} /></div>
              <h1>Bem-vinda à recepção</h1>
              <p>Acesso ao evento</p>
            </div>
          </header>
          <form onSubmit={entrar} style={{background:'white',marginTop:18,padding:22,borderRadius:20,border:'1px solid var(--borda)',display:'grid',gap:16}}>
            <div style={{display:'grid',gap:7}}>
              <label htmlFor="codigo-evento" style={{fontWeight:700,color:'var(--ameixa)'}}>Código do evento</label>
              <input id="codigo-evento" value={codigoEvento} onChange={e=>{setCodigoEvento(formatarDataEvento(e.target.value));setAcessoMensagem('');}} placeholder="DD/MM/AAAA" inputMode="numeric" maxLength={10} autoComplete="off" required />
              <small style={{color:'var(--suave)'}}>Para o evento de teste: 01/11/2026</small>
            </div>
            <div style={{display:'grid',gap:7}}>
              <label htmlFor="recepcionista" style={{fontWeight:700,color:'var(--ameixa)'}}>Recepcionista</label>
              <select id="recepcionista" value={recepcionista} onChange={e=>setRecepcionista(e.target.value)}>
                {RECEPCIONISTAS.map(nome=><option key={nome} value={nome}>{nome}</option>)}
              </select>
            </div>
            {acessoMensagem && <p role="alert">{acessoMensagem}</p>}
            <button type="submit" className="add">Entrar no evento</button>
          </form>
          <p style={{fontSize:12,color:'var(--suave)',textAlign:'center',lineHeight:1.5}}>Versão de teste: a seleção do nome não autentica a recepcionista. A autorização segura dos dados continua pendente.</p>
        </>
      ) : (
        <>
          <header>
            <div>
              <div style={{display:"flex",alignItems:"center",gap:12,marginBottom:10}}><span style={{display:"inline-flex",background:"white",borderRadius:"50%",padding:6,width:65,height:65,alignItems:"center",justifyContent:"center",overflow:"hidden",flexShrink:0}}><img src={MONOGRAMA_PM} alt="Monograma pm" style={{width:"100%",height:"100%",objectFit:"contain",borderRadius:"50%"}} /></span><span className="eyebrow">PM CERIMONIAL</span></div>
              <h1>{eventoId === EVENTOS_TESTE['01/11/2026'] ? 'Allan & Luciana' : 'Recepção de convidados'}</h1>
              <p>Evento {codigoEvento} · {recepcionista}</p>
            </div>
            <button onClick={sair} style={{border:'1px solid #f0d8e1',borderRadius:12,background:'transparent',color:'white',padding:'10px 13px',cursor:'pointer'}}>Trocar evento</button>
          </header>
          {erro && <p role="alert">{erro}</p>}
          {aviso && !carregando && <p role="status" style={{padding:'14px',background:'#fff6ee',border:'1px solid #e7d4bf',borderRadius:'12px',color:'#6b4939'}}>{aviso}</p>}
          <section className="stats">
            <div><b>{convidados.length}</b><span>Convidados</span></div>
            <div><b>{presentes}</b><span>Presentes</span></div>
            <div><b>{convidados.length - presentes}</b><span>Pendentes</span></div>
          </section>
          <section aria-label="Resumo infantil" style={{background:'#fff',border:'1px solid var(--borda)',borderRadius:16,padding:'14px 18px',margin:'-4px 0 16px',display:'flex',justifyContent:'space-between',alignItems:'center',gap:12}}>
            <span style={{color:'var(--ameixa)',fontWeight:700}}>Crianças presentes</span>
            <strong style={{fontSize:28,color:'var(--vinho)'}}>{criancasPresentes}</strong>
          </section>
          <nav aria-label="Abas do evento" style={{display:'grid',gridTemplateColumns:'repeat(5,minmax(0,1fr))',gap:5,margin:'12px 0 18px'}}>
            {[['todos','Todos'],['presentes','Presentes'],['pendentes','Pendentes'],['mesas','Mesas'],['buffet','Buffet']].map(([valor, texto]) => (
              <button key={valor} type="button" className={filtro === valor ? 'active' : ''}
                onClick={() => {setFiltro(valor);setBusca('');setAlterandoMesaId(null);}}
                style={{padding:'11px 3px',fontSize:12,minWidth:0,whiteSpace:'nowrap'}}>
                {texto}
              </button>
            ))}
          </nav>
          {filtro === 'buffet' ? (
          <section style={{background:'#fff',border:'1px solid var(--borda)',borderRadius:16,padding:'15px 18px',marginBottom:16}} aria-label="Faixas etárias do buffet">
            <div style={{display:'flex',justifyContent:'space-between',alignItems:'center',gap:10,flexWrap:'wrap'}}>
              <strong style={{color:'var(--ameixa)'}}>Crianças • buffet</strong>
              <button type="button" onClick={() => {setEditandoFaixas(v=>!v);setMensagemFaixas('');}} style={{background:'#f3e7eb',border:0,borderRadius:10,padding:'9px 12px',color:'var(--vinho)',fontWeight:700}}>{faixas ? 'Alterar faixas' : 'Configurar faixas'}</button>
            </div>
            {faixas ? (
              <div style={{display:'grid',gridTemplateColumns:'repeat(3,minmax(0,1fr))',gap:8,marginTop:12,textAlign:'center'}}>
                <div><strong style={{display:'block',fontSize:23,color:'var(--vinho)'}}>{criancasIsentas}</strong><small>Isentas (até {faixas.isento_ate} anos)</small></div>
                <div><strong style={{display:'block',fontSize:23,color:'var(--vinho)'}}>{criancasMeia}</strong><small>Meia ({faixas.isento_ate+1}–{faixas.meia_ate} anos)</small></div>
                <div><strong style={{display:'block',fontSize:23,color:'var(--vinho)'}}>{criancasIntegral}</strong><small>Integral (acima de {faixas.meia_ate})</small></div>
              </div>
            ) : <p style={{fontSize:13,color:'var(--suave)',margin:'9px 0 0'}}>Defina as regras do buffet para calcular as faixas das crianças presentes.</p>}
            {editandoFaixas && (
              <form onSubmit={guardarFaixas} style={{display:'grid',gap:9,marginTop:14}}>
                <label htmlFor="isento-ate">Idade máxima isenta</label>
                <input id="isento-ate" inputMode="numeric" type="number" min="0" max="17" value={limiteIsento} onChange={e=>setLimiteIsento(e.target.value)} required />
                <label htmlFor="meia-ate">Idade máxima de meia cobrança</label>
                <input id="meia-ate" inputMode="numeric" type="number" min="0" max="17" value={limiteMeia} onChange={e=>setLimiteMeia(e.target.value)} required />
                <button type="submit" className="add" disabled={salvandoFaixas}>{salvandoFaixas ? 'Salvando...' : 'Salvar faixas do evento'}</button>
                <small style={{color:'var(--suave)'}}>Idades acima do segundo limite entram na faixa integral. Regras válidas para crianças de 0 a 17 anos.</small>
              </form>
            )}
            {mensagemFaixas && <p role="status" style={{fontSize:13,color:'var(--suave)',margin:'8px 0 0'}}>{mensagemFaixas}</p>}
          </section>
          ) : (
            <>
              {filtro === 'mesas' ? (
                <section style={{background:'#fff',border:'1px solid var(--borda)',borderRadius:16,padding:16,marginBottom:15}}>
                  <label htmlFor="mesa-selecionada" style={{display:'block',fontWeight:700,color:'var(--ameixa)',marginBottom:8}}>Escolha uma mesa ou setor</label>
                  <select id="mesa-selecionada" value={mesaAtual}
                    onChange={e => {setMesaSelecionada(e.target.value);setAlterandoMesaId(null);}}
                    style={{width:'100%'}}>
                    {mesas.map(m => <option key={m} value={m}>{m}</option>)}
                  </select>
                  <p style={{margin:'12px 0 0',color:'var(--suave)',fontSize:14}}>
                    {convidadosDaMesa.length} convidados · {presentesDaMesa} presentes · {convidadosDaMesa.length - presentesDaMesa} pendentes
                  </p>
                </section>
              ) : (
                <section className="tools">
                  <button type="button" className="add" onClick={adicionar} disabled={carregando || ocupado}>+ Convidado extra</button>
                </section>
              )}
              <section className="tools">
                <input aria-label="Pesquisar convidado" value={busca}
                  onChange={e => setBusca(e.target.value)} placeholder="Pesquisar convidado..." />
              </section>
              <section className="list">
                {carregando && <p role="status">Atualizando convidados...</p>}
                {(filtro === 'mesas'
                  ? convidadosDaMesa.filter(c => (c.nome || '').toLowerCase().includes(busca.toLowerCase()))
                  : lista
                ).map(c => {
                  const presente = presentesIds.has(c.id);
                  return (
                    <article key={c.id} className={presente ? 'checked' : ''}>
                      <div>
                        <h2>{c.nome}</h2>
                        <p>{apresentarMesa(c.mesa)}{ehCrianca(c) ? ` · Criança · ${c.idade} anos` : ''}</p>
                      </div>
                      <div style={{display:'grid',gap:8,width:'100%'}}>
                        <button disabled={ocupado || carregando} onClick={() => check(c)}>
                          {presente ? '✓ Presente' : 'Fazer check-in'}
                        </button>
                        <button type="button" disabled={ocupado || carregando}
                          onClick={() => confirmarIdade(c)}
                          style={{border:'1px solid var(--borda)',borderRadius:10,padding:'9px 12px',background:'#fff',color:'var(--vinho)',fontSize:12,fontWeight:600,cursor:'pointer',width:'100%'}}>
                          {ehCrianca(c) ? 'Alterar idade da criança' : 'É criança? Informar idade'}
                        </button>
                        {filtro === 'mesas' && (alterandoMesaId === c.id ? (
                          <div style={{display:'grid',gap:8,padding:10,background:'#faf5f7',borderRadius:12}}>
                            <label htmlFor={'nova-mesa-'+c.id} style={{fontSize:13,fontWeight:700}}>Nova mesa ou setor</label>
                            <input id={'nova-mesa-'+c.id} value={novaMesa}
                              onChange={e=>setNovaMesa(e.target.value)} placeholder="Ex.: 08 ou Setor Jardim" />
                            <div style={{display:'flex',gap:8}}>
                              <button type="button" disabled={ocupado} onClick={()=>setAlterandoMesaId(null)}
                                style={{flex:1,whiteSpace:'normal'}}>Cancelar</button>
                              <button type="button" disabled={ocupado} onClick={()=>salvarMesa(c)}
                                style={{flex:1,background:'var(--vinho)',color:'#fff',whiteSpace:'normal'}}>Confirmar</button>
                            </div>
                          </div>
                        ) : (
                          <button type="button" disabled={ocupado || carregando}
                            onClick={()=>abrirAlteracaoMesa(c)}
                            style={{border:'1px solid var(--borda)',borderRadius:10,padding:'9px 12px',background:'#fff',color:'var(--vinho)',fontSize:12,fontWeight:600,cursor:'pointer',width:'100%'}}>
                            Alterar mesa
                          </button>
                        ))}
                      </div>
                    </article>
                  );
                })}
                {!carregando && (filtro === 'mesas'
                  ? !convidadosDaMesa.some(c => (c.nome || '').toLowerCase().includes(busca.toLowerCase()))
                  : !lista.length
                ) && !aviso && !erro && <div className="empty">Nenhum convidado encontrado.</div>}
              </section>
            </>
          )}
        </>
      )}
      <footer>PM Cerimonial · Versão de teste · Acesso seguro em desenvolvimento</footer>
    </main>
  );
}
